export default LoadingOverlay;

import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are a world-class academic transcriber specializing in high-density, shorthand notes. 
Your goal is to extract key takeaways from the provided lecture (audio, video, or text) in a very specific style:
- Extremely concise and brief. 
- Minimize the number of words used, NOT the amount of information.
- Style: Simple bullet points only.
- NO headings, NO subheadings, NO bold text for titles.
- Use abbreviations and shorthand (e.g., "M/C" for most common, "d/t" for due to, "w/" for with, "tx" for treatment, "r/o" for rule out, "HU" for hyperuricemia, etc.).
- Each bullet point should be a single nugget of information.
- Do not miss any important facts, data points, or clinical/technical details.

Example Style:
- gout: M/C form of inflam arthritis d/t hyperurecima in synovium
- monosodium urate crystals
- M:F = 5:1 >40 yrs
- chronic HU > 6.8 mg/dl precedes gout by 20-30 yrs
- high purine meat and seafood, metbolic syndrome (5), renal impairment, increase cell turnover, low-dose aspirin, diuretics, calcinurin inhibitors
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-pro-preview";

export const processLectureFile = async (
  fileBase64: string,
  mimeType: string,
  fileName: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: fileBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Extract shorthand notes from this file: "${fileName}". Follow the system instruction strictly.`,
          },
        ],
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.2,
      },
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini File API Error:", error);
    throw new Error(error.message || "Failed to process file.");
  }
};

export const processLectureText = async (
  text: string,
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ text: `Lecture Title: ${title}\n\nContent:\n${text}` }],
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.2,
      },
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini Text API Error:", error);
    throw new Error(error.message || "Failed to process text.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { NoteEntry, ProcessingState } from './types';
import { processLectureFile, processLectureText } from './services/geminiService';
import HistorySidebar from './components/HistorySidebar';
import LoadingOverlay from './components/LoadingOverlay';

type InputMode = 'media' | 'text';

const App: React.FC = () => {
  const [history, setHistory] = useState<NoteEntry[]>([]);
  const [currentNote, setCurrentNote] = useState<NoteEntry | null>(null);
  const [inputMode, setInputMode] = useState<InputMode>('media');
  const [rawText, setRawText] = useState('');
  const [textTitle, setTextTitle] = useState('');
  const [processing, setProcessing] = useState<ProcessingState>({
    isProcessing: false,
    progress: '',
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('lecture_notes_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('lecture_notes_history', JSON.stringify(history));
  }, [history]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setProcessing({ isProcessing: true, progress: 'Reading file...' });

    try {
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve, reject) => {
        reader.onload = () => {
          const result = reader.result as string;
          const base64 = result.split(',')[1];
          resolve(base64);
        };
        reader.onerror = reject;
      });
      reader.readAsDataURL(file);

      const base64 = await base64Promise;
      setProcessing({ isProcessing: true, progress: 'AI is analyzing and shrinking content...' });

      const extractedContent = await processLectureFile(base64, file.type, file.name);

      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: file.name.split('.')[0] || 'Untitled Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: file.name,
      };

      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleTextShrink = async () => {
    if (!rawText.trim()) return;

    setProcessing({ isProcessing: true, progress: 'Compressing information...' });

    try {
      const title = textTitle.trim() || 'Pasted Text Lecture';
      const extractedContent = await processLectureText(rawText, title);

      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: 'Text Input',
      };

      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setRawText('');
      setTextTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const deleteNote = (id: string) => {
    setHistory(prev => prev.filter(n => n.id !== id));
    if (currentNote?.id === id) setCurrentNote(null);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <HistorySidebar 
        history={history} 
        onSelect={setCurrentNote} 
        onDelete={deleteNote}
        currentId={currentNote?.id}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />

      <main className="flex-1 p-4 md:p-8 flex flex-col max-w-5xl mx-auto w-full">
        <header className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight flex items-center gap-2">
              <i className="fa-solid fa-bolt-lightning text-yellow-500"></i>
              Note Shrinker
            </h1>
            <p className="text-slate-500 mt-1">Maximum density. Minimum words.</p>
          </div>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="md:hidden p-2 text-slate-600 hover:text-slate-900"
          >
            <i className="fa-solid fa-bars text-xl"></i>
          </button>
        </header>

        {/* Input Switcher */}
        <div className="flex bg-slate-200 p-1 rounded-xl w-fit mb-6 self-center shadow-inner">
          <button 
            onClick={() => setInputMode('media')}
            className={`px-6 py-2 rounded-lg text-sm font-semibold transition-all ${inputMode === 'media' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <i className="fa-solid fa-microphone-lines mr-2"></i>
            Media Record
          </button>
          <button 
            onClick={() => setInputMode('text')}
            className={`px-6 py-2 rounded-lg text-sm font-semibold transition-all ${inputMode === 'text' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <i className="fa-solid fa-align-left mr-2"></i>
            Paste Text
          </button>
        </div>

        {/* Input Area */}
        <div className="mb-8">
          {inputMode === 'media' ? (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 text-center hover:border-blue-300 transition-colors group cursor-pointer relative overflow-hidden"
              onClick={() => fileInputRef.current?.click()}>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                accept="audio/*,video/*,application/pdf,text/plain" 
                className="hidden"
              />
              <div className="flex flex-col items-center py-4">
                <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-file-arrow-up text-2xl"></i>
                </div>
                <h3 className="text-lg font-semibold text-slate-800">Upload Lecture Source</h3>
                <p className="text-slate-500 text-sm mt-1">Audio, Video, PDF, or TXT</p>
              </div>
              <div className="absolute inset-0 bg-blue-500/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            </section>
          ) : (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-4">
              <input 
                type="text"
                placeholder="Lecture Title (optional)"
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm"
                value={textTitle}
                onChange={(e) => setTextTitle(e.target.value)}
              />
              <textarea 
                className="w-full min-h-[160px] p-4 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm resize-none"
                placeholder="Paste your lecture transcript or long-form notes here..."
                value={rawText}
                onChange={(e) => setRawText(e.target.value)}
              ></textarea>
              <button 
                onClick={handleTextShrink}
                disabled={!rawText.trim()}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white font-bold py-3 px-6 rounded-xl flex items-center justify-center gap-2 transition-colors"
              >
                <i className="fa-solid fa-wand-magic-sparkles"></i>
                Shrink Notes
              </button>
            </section>
          )}
        </div>

        {/* Notes Display */}
        {currentNote ? (
          <div className="flex-1 flex flex-col bg-white rounded-2xl shadow-md border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
              <div>
                <h2 className="font-bold text-slate-800 flex items-center gap-2">
                  <i className="fa-solid fa-file-lines text-blue-500"></i>
                  {currentNote.title}
                </h2>
                <span className="text-xs text-slate-400 font-mono">
                  {new Date(currentNote.timestamp).toLocaleString()} • {currentNote.fileName}
                </span>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => copyToClipboard(currentNote.content)}
                  className="p-2 hover:bg-slate-200 rounded-lg text-slate-600 transition-colors"
                  title="Copy to clipboard"
                >
                  <i className="fa-regular fa-copy"></i>
                </button>
              </div>
            </div>
            <div className="p-6 overflow-y-auto flex-1 bg-white">
              <div className="mono text-sm leading-relaxed whitespace-pre-wrap text-slate-700">
                {currentNote.content}
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl py-12">
            <i className="fa-solid fa-paste text-4xl mb-4 opacity-20"></i>
            <p className="text-sm">No lecture notes selected. Upload or paste one to start!</p>
          </div>
        )}

        {processing.error && (
          <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600 text-sm flex items-center gap-3">
            <i className="fa-solid fa-circle-exclamation"></i>
            <span>{processing.error}</span>
            <button 
              onClick={() => setProcessing({ ...processing, error: undefined })}
              className="ml-auto p-1 hover:bg-red-100 rounded"
            >
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        )}
      </main>

      <LoadingOverlay active={processing.isProcessing} message={processing.progress} />
    </div>
  );
};

