              onClick={() => setProcessing({ ...processing, error: undefined })}
              className="ml-auto p-1 hover:bg-red-100 rounded"
            >
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        )}
      </main>

      <LoadingOverlay active={processing.isProcessing} message={processing.progress} />
    </div>
  );
};

