 * - No Markdown (no #, **, _, etc.)
 * - No LaTeX (no $ notation, no backslashes)
 * - Unicode symbols only (→, ↓, ↑, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •)
 * - Heavy use of specific abbreviations
 * - 100% information retention
 */
const SYSTEM_INSTRUCTION = `
You are a high-precision lossless shorthand engine. Your task is to transcribe lecture content into high-density shorthand without losing a single detail.

STRICT FORMATTING RULES:
1. NO MARKDOWN: Never use bold (**), headers (#), or italics (_). Output must be pure plain text.
2. NO LATEX: Never use $ notation or backslash commands like \\rightarrow. Use actual characters.
3. SYMBOLS: Use Unicode only: →, ←, ↑, ↓, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •, > , <, @, %, w/, w/o, d/t.
4. LOSSLESS CONTENT: You must capture every name, date, definition, logic step, and specific data point. If the input is long, the output must be long and detailed. Do NOT summarize or omit facts.
5. SHORTHAND STYLE (ABBREVIATIONS): 
   - Use aggressive abbreviations: dz (disease), inflamm (inflammatory), involv (involvement), assoc (associated), dx (diagnosis), tx (treatment), sx (symptoms), pt (patient), nl (normal), fxn (function), hx (history), fam hx (family history), m/c (most common), rx (prescription), f/u (follow up), b/c (because), BP (blood pressure), unilat (unilateral), asymm (asymmetric), SIJ (sacroiliac joint), info (information), intro (introduction).
   - Use '-' for bullet points.

STRUCTURE:
1. Detailed Shorthand list (capturing every detail).
2. A line of 30 equal signs: ==============================
3. KEY TAKEAWAYS (also in shorthand).

EXAMPLE STYLE (STRICTLY FOLLOW THIS):
- SpAs: group of seroneg (-RF) inflam spine dz sharing sacroiliitis, spine involv, HLA-B27 assoc
- spectrum: AS, ReA, IBD-associated, PsA, undiff SpA
- pathophys: autoimmune in genetically susceptible + enviro trigger
- prev: 0.7-49/10k; M>F 3:1; dx often delayed
- inflam BP criteria (4/5): onset <40-45, insidious, >3 mos duration, morning stiffness >1 hr, improves w/ exercise (not rest), night pain
- tx goals: relieve sx, maintain fxn, prevent kyphosis
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  thinkingConfig: { thinkingBudget: 24576 }, // max thinking budget for gemini-3-flash-preview
};

export const processLectureFile = async (
  fileBase64: string,
  mimeType: string,
  fileName: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: fileBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Lossless shorthand transcription for: "${fileName}". Include 100% of information using extreme abbreviations. No markdown. Use Unicode symbols like →.`,
          },
        ],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash File Error:", error);
    throw new Error(error.message || "Failed to process file with Gemini 3 Flash.");
  }
};

