                {currentNote.content}
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-2xl py-12">
            <i className="fa-solid fa-paste text-4xl mb-4 opacity-20"></i>
