import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";

/**
 * LOSSLESS SHORTHAND INSTRUCTION:
 * - No Markdown (no #, **, _, etc.)
 * - No LaTeX (no $ notation, no backslashes)
 * - Unicode symbols only (→, ↓, ↑, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •)
 * - Heavy use of specific abbreviations
 * - 100% information retention
 */
const SYSTEM_INSTRUCTION = `
You are a high-precision lossless shorthand engine. Your task is to transcribe lecture content into high-density shorthand without losing a single detail.

STRICT FORMATTING RULES:
1. NO MARKDOWN: Never use bold (**), headers (#), or italics (_). Output must be pure plain text.
2. NO LATEX: Never use $ notation or backslash commands like \\rightarrow. Use actual characters.
3. SYMBOLS: Use Unicode only: →, ←, ↑, ↓, Δ, Σ, ≈, ≠, ±, ∞, ∴, ∵, •, > , <, @, %, w/, w/o, d/t.
4. LOSSLESS CONTENT: You must capture every name, date, definition, logic step, and specific data point. If the input is long, the output must be long and detailed. Do NOT summarize or omit facts.
5. SHORTHAND STYLE (ABBREVIATIONS): 
   - Use aggressive abbreviations: dz (disease), inflamm (inflammatory), involv (involvement), assoc (associated), dx (diagnosis), tx (treatment), sx (symptoms), pt (patient), nl (normal), fxn (function), hx (history), fam hx (family history), m/c (most common), rx (prescription), f/u (follow up), b/c (because), BP (blood pressure), unilat (unilateral), asymm (asymmetric), SIJ (sacroiliac joint), info (information), intro (introduction).
   - Use '-' for bullet points.

STRUCTURE:
1. Detailed Shorthand list (capturing every detail).
2. A line of 30 equal signs: ==============================
3. KEY TAKEAWAYS (also in shorthand).

EXAMPLE STYLE (STRICTLY FOLLOW THIS):
- SpAs: group of seroneg (-RF) inflam spine dz sharing sacroiliitis, spine involv, HLA-B27 assoc
- spectrum: AS, ReA, IBD-associated, PsA, undiff SpA
- tx goals: relieve sx, maintain fxn, prevent kyphosis
`;

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

const GENERATION_CONFIG = {
  systemInstruction: SYSTEM_INSTRUCTION,
  temperature: 0.1,
  thinkingConfig: { thinkingBudget: 24576 },
};

export const processLectureFile = async (
  fileBase64: string,
  mimeType: string,
  fileName: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: fileBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Lossless shorthand transcription for: "${fileName}". Include 100% of information using extreme abbreviations. No markdown. Use Unicode symbols like →.`,
          },
        ],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash File Error:", error);
    throw new Error(error.message || "Failed to process file with Gemini 3 Flash.");
  }
};

export const processLectureText = async (
  text: string,
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ text: `Lecture: ${title}\n\nPerform lossless shorthand transcription with heavy abbreviations on this raw content:\n${text}` }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Text Error:", error);
    throw new Error(error.message || "Failed to process text.");
  }
};

export const processLectureUrl = async (
  url: string
): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `You are provided with a YouTube link to a lecture: ${url}. 
          Please find the transcript or specific content of this video and perform a LOSSLESS SHORTHAND TRANSCRIPTION. 
          Capture 100% of the information shared in the video. Use extreme abbreviations. No markdown. Use Unicode symbols like →.` 
        }],
      },
      config: {
        ...GENERATION_CONFIG,
        tools: [{ googleSearch: {} }],
      },
    });

    if (!response.text) throw new Error("No response generated.");

    let output = response.text;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (sources && sources.length > 0) {
      output += "\n\n==============================\nSOURCES FOUND:\n";
      sources.forEach((chunk: any) => {
        if (chunk.web?.uri) {
          output += `• ${chunk.web.title || 'Source'}: ${chunk.web.uri}\n`;
        }
      });
    }

    return output;
  } catch (error: any) {
    console.error("Gemini 3 Flash URL Error:", error);
    throw new Error(error.message || "Failed to process URL content.");
  }
};

export const combineLectureSources = async (
  sources: string[],
  title: string
): Promise<string> => {
  const ai = getAI();
  try {
    const combinedInput = sources.map((s, i) => `SOURCE ${i + 1}:\n${s}`).join("\n\n---\n\n");
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [{ 
          text: `Lecture Title: ${title}

          I have multiple sources (notes/transcripts) of the same lecture. 
          Your goal is to MERGE them into ONE unified, comprehensive, lossless shorthand transcript.

          RULES:
          1. DE-DUPLICATE: If information is present in multiple sources, include it only once.
          2. LOSSLESS: Do NOT miss any detail. If Source A has a fact that Source B lacks, include it.
          3. SYNERGY: Combine overlapping sentences into the most detailed version possible.
          4. STYLE: Use extreme shorthand abbreviations (pt, dz, tx, etc.) and Unicode symbols (→).
          5. NO MARKDOWN: Output must be pure plain text.

          CONTENT SOURCES TO MERGE:
          ${combinedInput}` 
        }],
      },
      config: GENERATION_CONFIG,
    });

    if (!response.text) throw new Error("No response generated.");
    return response.text;
  } catch (error: any) {
    console.error("Gemini 3 Flash Merge Error:", error);
    throw new Error(error.message || "Failed to merge sources.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { NoteEntry, ProcessingState } from './types';
import { processLectureFile, processLectureText, processLectureUrl, combineLectureSources } from './services/geminiService';
import HistorySidebar from './components/HistorySidebar';
import LoadingOverlay from './components/LoadingOverlay';

type InputMode = 'media' | 'text' | 'youtube' | 'combine';

const App: React.FC = () => {
  const [history, setHistory] = useState<NoteEntry[]>([]);
  const [currentNote, setCurrentNote] = useState<NoteEntry | null>(null);
  const [inputMode, setInputMode] = useState<InputMode>('media');

  // Text state
  const [rawText, setRawText] = useState('');
  const [textTitle, setTextTitle] = useState('');

  // Youtube state
  const [ytLink, setYtLink] = useState('');

  // Combine state
  const [combineSources, setCombineSources] = useState<string[]>(['', '']);
  const [combineTitle, setCombineTitle] = useState('');

  const [processing, setProcessing] = useState<ProcessingState>({
    isProcessing: false,
    progress: '',
  });
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('lecture_notes_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('lecture_notes_history', JSON.stringify(history));
  }, [history]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setProcessing({ isProcessing: true, progress: 'Reading source file...' });

    try {
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve, reject) => {
        reader.onload = () => {
          const result = reader.result as string;
          const base64 = result.split(',')[1];
          resolve(base64);
        };
        reader.onerror = reject;
      });
      reader.readAsDataURL(file);

      const base64 = await base64Promise;
      setProcessing({ isProcessing: true, progress: 'Gemini 3 Flash is mapping every detail...' });

      const extractedContent = await processLectureFile(base64, file.type, file.name);

      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: file.name.split('.')[0] || 'Untitled Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: file.name,
      };

      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleTextShrink = async () => {
    if (!rawText.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Performing lossless encoding...' });
    try {
      const title = textTitle.trim() || 'Pasted Text Lecture';
      const extractedContent = await processLectureText(rawText, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: 'Text Input',
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setRawText('');
      setTextTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleYoutubeShrink = async () => {
    if (!ytLink.trim()) return;
    setProcessing({ isProcessing: true, progress: 'Locating lecture content and transcript...' });
    try {
      const extractedContent = await processLectureUrl(ytLink);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: 'YouTube Lecture',
        content: extractedContent,
        timestamp: Date.now(),
        fileName: ytLink,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setYtLink('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const handleMergeShrink = async () => {
    const validSources = combineSources.filter(s => s.trim() !== '');
    if (validSources.length < 2) return;
    setProcessing({ isProcessing: true, progress: 'Merging and de-duplicating sources...' });
    try {
      const title = combineTitle.trim() || 'Merged Lecture Sources';
      const extractedContent = await combineLectureSources(validSources, title);
      const newNote: NoteEntry = {
        id: Date.now().toString(),
        title: title,
        content: extractedContent,
        timestamp: Date.now(),
        fileName: `Merged (${validSources.length} sources)`,
      };
      setHistory(prev => [newNote, ...prev]);
      setCurrentNote(newNote);
      setCombineSources(['', '']);
      setCombineTitle('');
      setProcessing({ isProcessing: false, progress: '' });
    } catch (err: any) {
      setProcessing({ isProcessing: false, progress: '', error: err.message });
    }
  };

  const updateCombineSource = (index: number, val: string) => {
    const next = [...combineSources];
    next[index] = val;
    setCombineSources(next);
  };

  const addCombineField = () => setCombineSources([...combineSources, '']);
  const removeCombineField = (index: number) => {
    if (combineSources.length <= 2) return;
    setCombineSources(combineSources.filter((_, i) => i !== index));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const deleteNote = (id: string) => {
    setHistory(prev => prev.filter(n => n.id !== id));
    if (currentNote?.id === id) setCurrentNote(null);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <HistorySidebar 
        history={history} 
        onSelect={setCurrentNote} 
        onDelete={deleteNote}
        currentId={currentNote?.id}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />

      <main className="flex-1 p-4 md:p-8 flex flex-col max-w-5xl mx-auto w-full">
        <header className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-800 tracking-tight flex items-center gap-2">
              <i className="fa-solid fa-bolt-lightning text-yellow-500"></i>
              Note Shrinker
            </h1>
            <p className="text-slate-500 mt-1">Lossless extraction. Pro Shorthand.</p>
          </div>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="md:hidden p-2 text-slate-600 hover:text-slate-900"
          >
            <i className="fa-solid fa-bars text-xl"></i>
          </button>
        </header>

        {/* Input Switcher */}
        <div className="flex bg-slate-200 p-1 rounded-xl w-fit mb-6 self-center shadow-inner overflow-x-auto max-w-full">
          {[
            { id: 'media', icon: 'fa-microphone-lines', label: 'Media' },
            { id: 'text', icon: 'fa-align-left', label: 'Text' },
            { id: 'youtube', icon: 'fa-youtube', label: 'YouTube', color: 'text-red-500' },
            { id: 'combine', icon: 'fa-layer-group', label: 'Combine' }
          ].map((tab) => (
            <button 
              key={tab.id}
              onClick={() => setInputMode(tab.id as InputMode)}
              className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${inputMode === tab.id ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <i className={`fa-solid ${tab.id === 'youtube' ? 'fa-brands' : 'fa-solid'} ${tab.icon} mr-2 ${tab.color || ''}`}></i>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Input Area */}
        <div className="mb-8">
          {inputMode === 'media' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 text-center hover:border-blue-300 transition-colors group cursor-pointer relative overflow-hidden"
              onClick={() => fileInputRef.current?.click()}>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                accept="audio/*,video/*,application/pdf,text/plain" 
                className="hidden"
              />
              <div className="flex flex-col items-center py-4">
                <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-file-arrow-up text-2xl"></i>
                </div>
                <h3 className="text-lg font-semibold text-slate-800">Process Lecture Source</h3>
                <p className="text-slate-500 text-sm mt-1">Recordings or Documents (Full retention)</p>
              </div>
              <div className="absolute inset-0 bg-blue-500/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
            </section>
          )}

          {inputMode === 'text' && (
            <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex flex-col gap-4">
              <input 
                type="text"
                placeholder="Lecture Title (optional)"
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm font-medium"
                value={textTitle}
                onChange={(e) => setTextTitle(e.target.value)}
              />
              <textarea 
                className="w-full min-h-[160px] p-4 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-sm resize-none"
                placeholder="Paste the content here for lossless shorthand conversion..."
                value={rawText}
                onChange={(e) => setRawText(e.target.value)}
              ></textarea>
              <button 
                onClick={handleTextShrink}
                disabled={!rawText.trim()}
                className="bg-blue-600 hover:bg-blue-700 disabled:bg-slate-300 text-white font-bold py-3 px-6 rounded-xl flex items-center justify-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <i className="fa-solid fa-wand-magic-sparkles"></i>
                Extract Lossless Notes
